import { API, graphqlOperation } from "aws-amplify";
import { initiate_org_refill_vault_request } from "@/graphql/mutations.js";
import { get_expense_groups_users } from "@/mixins/GetExpenseGroups.js";
export default {
  name: "WalletDialog",
  mixins: [get_expense_groups_users],
  props: {
    walletDialog: {
      type: Boolean,
      required: true
    }
  },
  data() {
    return {
      loading: false,
      expenseGroupHead: [],
      formGroup: "",
      formAmount: "",
      formComments: ""
    };
  },
  async mounted() {
    await this.get_expense_groups_users();
    this.expenseGroupHead = [];
    if (this.listExpense && this.listExpense.length > 0) {
      this.listExpense.forEach(element => {
        this.expenseGroupHead.push({
          title: element.expense_group_name,
          value: String(element.expense_group_id)
        });
      });
      if (!this.formGroup) {
        this.formGroup = this.expenseGroupHead[0].value;
      }
    } else {
      this.expenseGroupHead.push({
        title: "DEFAULT",
        value: "DEFAULT"
      });
      this.formGroup = "DEFAULT";
    }
  },
  methods: {
    is_number(evt) {
      evt = evt ? evt : window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      } else {
        return true;
      }
    },
    process(event) {
      if (event.type == "paste") {
        var clipboardData = event.clipboardData || window.clipboardData;
        var pastedData = clipboardData.getData("Text");
        if (isNaN(pastedData)) {
          event.preventDefault();
        } else {
          return;
        }
      }
      var keyCode = event.keyCode || event.which;
      if (keyCode >= 96 && keyCode <= 105) {
        keyCode -= 48;
      }
      var charValue = String.fromCharCode(keyCode);
      if (isNaN(parseInt(charValue)) && event.keyCode != 8) {
        event.preventDefault();
      }
    },
    async submitWalletRequest() {
      const {
        valid
      } = await this.$refs.form1.validate();
      // console.log(valid);
      if (valid) {
        this.loading = true;
        try {
          let result = await API.graphql(graphqlOperation(initiate_org_refill_vault_request, {
            input: {
              requested_amount: Number(this.formAmount),
              expense_description: this.formComments
            }
          }));
          this.loading = false;
          var response = JSON.parse(result.data.initiate_org_refill_vault_request);
          if (response.Status == "SUCCESS") {
            this.$emit("successMsg", response.Message);
            this.resetForm();
            this.$emit("clicked");
          } else {
            this.$emit("errorMsg", response.Message);
          }
        } catch (error) {
          console.log(error);
          this.loading = false;
          this.$emit("errorMsg", error.errors?.[0]?.message || error.message);
        }
      }
    },
    closeDialog() {
      this.resetForm();
      this.$emit("clicked");
    },
    resetForm() {
      this.formAmount = "";
      this.formGroup = "";
      this.formComments = "";
    }
  }
};
